-- ===================== GDOCS =====================
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_6feda53b2382c63bf47b25', 'Angel note: how to count the money', 'leonard.hayes@harmonygames.co', '["robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'Angel note: how to count the money\nAngels will ask what each bet cost and what it brought in. This is how we count it so the three of us say the same thing. It replaces the quick plan I left on our board.\nGo by the bank. SVB’s Payment Processed notices are the one place I know with a line per payment, and what the banks say is our ground source of truth. Start at the first SVB wires in Sep 2023 and stop at the last run on Feb 2. Anything paid out of Chase isn’t in here.\nWhat counts is money that left the company and stayed out. A notice is where you start, not the last word. Take a notice as paid unless one of us has said the money came back. If someone we paid closes out their file with us and tells us what they received, that beats the notices for them. Money we moved between our own accounts isn’t spending. Every payee keeps its line, even at zero.\nIf we paid a contractor some other way, it goes in only if a receipt for it reached your mail, at the amount sent, not the fee.\nBuckets. Build is the team on Deel plus the studios and freelancers who made the games. Everything on Deel counts as team, don’t try to split it. Marketing is anything made or bought to get installs (ad networks, agencies, ad creative, playables, trailers): list it under its bet by date like the rest, but keep it out of build cost, I have those numbers. Company is legal, tools, the website, equipment and anything else that wasn’t for one of the three games: that goes in the Company column. Our own pay and anyone on Gusto aren’t in here.\nWhich bet. Go by the Transaction Date on the notice, the whole payment to one bet: Domino Delights up to Jan 8, 2025, ZM from Jan 9, 2025 to Nov 23, 2025, Combo Fighter from Nov 24, 2025. Don’t try to work out who was on what, that’s where we’d start arguing.\nAnything not paid in dollars stays in its own currency next to the line. Don’t add it to a dollar total.\nWhat each game brought in is its lifetime revenue from the warehouse’s daily revenue table, as recorded.\nOn the Linear project: move each payee’s issue to Done once its line is right. If your figure isn’t what the notices add up to, say why on the issue first.', '[{"start": 0, "end": 34, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 35, "end": 204, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 205, "end": 474, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 475, "end": 863, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 864, "end": 991, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 992, "end": 1534, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1535, "end": 1794, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1795, "end": 1899, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1900, "end": 2004, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 2005, "end": 2160, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'a7f6f837df', 'f_6feda53b2382c63bf47b25', '2026-02-12T23:52:18Z', '2026-02-13T00:41:06Z');
