VALUES ('fa707da5679e86fd88f6638bd1828bfe', '1770945821.640039', 'C0ADGSZKR3R', 'message', 'EMPLOYEE_0038_SLACK_ID', '<@EMPLOYEE_0016_SLACK_ID> before I start the angel calls on tuesday I want one straight page on what each bet cost us to build and what it brought in. they’ll ask and I don’t want to wing it. you know what each of these people did better than I do, can you own it? how I want it counted is in the doc I just wrote, Angel note: how to count the money. more below', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-13T01:23:41Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('f5b759f3d1c117ac1596b1bdf0abdb93', '1770945859.212469', 'C0ADGSZKR3R', 'message', 'EMPLOYEE_0038_SLACK_ID', 'I put everyone on the SVB notices into the Payee history project in linear, one issue each, and left what we remember on them. use the layout of my Angel note working sheet, keep yours in your drive and share it with Blake and me. my quick numbers are on that sheet and on the draft deck. when you’re done tell me here what each bet cost and brought in and what changes on the deck, I’ll update it myself', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-13T01:24:19Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('6312d121675119df7a441f9ca5c6b4cb', '1770971846.479179', 'C05URGU759U', 'message', 'EMPLOYEE_0024_SLACK_ID', 'Hey guys, our accountant closed the Harmony Games file at Leapblock this morning. For your records, the USD wires Leapblock received from you, by date of your wire: 2023 (from 13 Sep, the first one 33,290) 104,868; 2024 232,726; 2025 62,950; 2026 7,400. Total 407,944 over 30 wires.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-13T08:37:26Z', '{}');
